    assert!(offset_of!(RouletteTable, randDistanceLow) == 2, "RouletteTable.randDistanceLow");
    assert!(offset_of!(RouletteTable, wheelSpeed) == 3, "RouletteTable.wheelSpeed");
    assert!(offset_of!(RouletteTable, wheelDelay) == 4, "RouletteTable.wheelDelay");
    assert!(offset_of!(RouletteTable, shroomish) == 6, "RouletteTable.shroomish");
